 static WebResourceResponse get(String url){long epoch=EPOCH.get();HttpsURLConnection c=null;java.util.concurrent.ScheduledFuture<?> deadline=null;java.util.concurrent.atomic.AtomicBoolean expired=new java.util.concurrent.atomic.AtomicBoolean();try{c=(HttpsURLConnection)new URL(url).openConnection();ACTIVE.add(c);final HttpsURLConnection connection=c;deadline=DEADLINES.schedule(()->{expired.set(true);connection.disconnect();},20,java.util.concurrent.TimeUnit.SECONDS);if(epoch!=EPOCH.get())return blocked();c.setInstanceFollowRedirects(false);c.setUseCaches(false);c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setRequestMethod("GET");int status=c.getResponseCode();if(status!=200)return blocked();String type=c.getContentType();if(type==null)return blocked();String mime=type.split(";",2)[0].trim();if(!java.util.Arrays.asList("text/html","text/javascript","application/javascript","text/css","image/png","image/webp","image/svg+xml").contains(mime))return blocked();ByteArrayOutputStream output=new ByteArrayOutputStream();try(InputStream input=c.getInputStream()){byte[] b=new byte[8192];for(int n;(n=input.read(b))!=-1;){if(expired.get()||epoch!=EPOCH.get()||output.size()+n>4194304)return blocked();output.write(b,0,n);}}if(expired.get()||epoch!=EPOCH.get())return blocked();HashMap<String,String> headers=new HashMap<>();headers.put("Cache-Control","no-store");headers.put("Referrer-Policy","no-referrer");headers.put("Content-Security-Policy","default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'none'; form-action 'none'; frame-src 'none'");headers.put("X-Content-Type-Options","nosniff");return new WebResourceResponse(mime,"UTF-8",200,"OK",headers,new ByteArrayInputStream(output.toByteArray()));}catch(Exception e){return blocked();}finally{if(deadline!=null)deadline.cancel(false);if(c!=null){ACTIVE.remove(c);c.disconnect();}}}
